begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('a9281000-0000-4000-8000-000000000001','serial-vet@example.test','{}'),('a9281000-0000-4000-8000-000000000002','serial-staff@example.test','{}');
update public.profiles set is_active = true where id in ('a9281000-0000-4000-8000-000000000001','a9281000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('a9281000-0000-4000-8000-000000000001','STAFF'),('a9281000-0000-4000-8000-000000000002','STAFF');

insert into public.user_roles(user_id,role) values('a9281000-0000-4000-8000-000000000001','DVM') on conflict do nothing;
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table requests(k text primary key,v jsonb); grant all on requests to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9281000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Certificate','Family','3035550100',null,'EMAIL','123 Test St, Boulder CO',null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Certificate dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
reset role;
insert into public.certificate_issuers(user_id,full_name,license_number,license_state,license_expires_on,practice_name,practice_address,practice_phone,verified_at,verification_reference,clinical_acceptance_at,active) values('a9281000-0000-4000-8000-000000000001','Dr Test','TEST-ONLY','CO',current_date+365,'Test practice','2619 Spruce Street, Boulder CO','3035550199',now(),'SYNTHETIC TEST VERIFICATION',now(),true);
set local role authenticated;
insert into fx select 'product',id from public.save_catalog_product(null,null,'Test rabies vaccine','vaccine','Test manufacturer','dose',3000,true);
select public.receive_inventory('a9281100-0000-4000-8000-000000000001','a9281100-0000-4000-8000-000000000002',(select id from fx where k='product'),'TEST-LOT',current_date+365,'Clinic',10,'Synthetic test stock');
select public.create_billing_invoice('a9281100-0000-4000-8000-000000000003',(select id from fx where k='client'));
insert into requests values('live',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id','a9281100-0000-4000-8000-000000000002','invoice_id','a9281100-0000-4000-8000-000000000003','quantity',1,'dose','1 mL','route','SC','site','right rear leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'next_due_on',current_date+365));
update requests set v=v||jsonb_build_object('alert_review',jsonb_build_object('source_hash',read_patient_treatment_alerts((v->>'pet_id')::uuid)->>'source_hash','acknowledged',true)) where k='live';
select public.record_patient_treatment('a9281100-0000-4000-8000-000000000004',(select v from requests where k='live'));
insert into requests values('details','{"administrator":"Test technician","rabies_tag_number":"TEST-TAG","usda_duration":"1 year","vaccine_type":"Killed virus","size_description":"20–50 lb","initial_or_booster":"initial","owner_business_phone_unavailable":true,"supervision_attested":true}');
-- Rabies serial number is a reviewed certificate detail distinct from the stock lot number.
insert into requests select 'no-serial',public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v from requests where k='details'));
select ok((select v->'details' ? 'vaccine_serial_number' from requests where k='no-serial'),'New rabies snapshots always carry the serial field');
select is((select v#>'{details,vaccine_serial_number}' from requests where k='no-serial'),'null'::jsonb,'Omitted serial is recorded as not recorded, never copied from the lot');
select is((select v#>>'{vaccinations,0,lot_number}' from requests where k='no-serial'),'TEST-LOT','Lot number remains the stock lot');
select is((select v->>'schema_version' from requests where k='no-serial'),'1','Rabies snapshot schema unchanged');
insert into requests select 'serial',public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":"  SER-123  "}' from requests where k='details'));
select is((select v#>>'{details,vaccine_serial_number}' from requests where k='serial'),'SER-123','Serial trimmed and recorded separately');
select is((select v#>>'{vaccinations,0,lot_number}' from requests where k='serial'),'TEST-LOT','Serial does not overwrite the lot');
select is(public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":"   "}' from requests where k='details'))#>'{details,vaccine_serial_number}','null'::jsonb,'Blank serial recorded as not recorded');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":123}' from requests where k='details'))$$,'23514','Invalid certificate detail type','Serial must be text');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||jsonb_build_object('vaccine_serial_number',repeat('x',201)) from requests where k='details'))$$,'23514','Vaccine serial number is too long','Serial length bounded');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select (v-'administrator')||'{"vaccine_serial_number":"SER-123"}' from requests where k='details'))$$,'23514',null,'Existing rabies validation still applies');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2,"vaccine_serial_number":"SER-123"}')$$,'23514',null,'General history does not accept a rabies serial');
select throws_ok($$select public.issue_vaccine_certificate('a9281100-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":"SER-123"}' from requests where k='details'),(select v from requests where k='no-serial'),'Dr Test',true)$$,'PT409',null,'A preview reviewed without the serial cannot sign a serial');
select lives_ok($$select public.issue_vaccine_certificate('a9281100-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":"  SER-123  "}' from requests where k='details'),(select v from requests where k='serial'),'Dr Test',true)$$,'Reviewed serial preview issues');
select is((select snapshot#>>'{details,vaccine_serial_number}' from public.vaccine_certificates where id='a9281100-0000-4000-8000-000000000005'),'SER-123','Issued snapshot freezes the serial');
select lives_ok($$select public.issue_vaccine_certificate('a9281100-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v||'{"vaccine_serial_number":"  SER-123  "}' from requests where k='details'),(select v from requests where k='serial'),'Dr Test',true)$$,'Lost-response retry returns the issued certificate');
select throws_ok($$select public.preview_vaccine_certificate_v2_internal((select id from fx where k='pet'),'rabies','a9281100-0000-4000-8000-000000000004',(select v from requests where k='details'))$$,'42501',null,'Browser cannot bypass the serial-aware preview');
reset role;
select * from finish();
rollback;
